def investigate(context, acquire):
    actions = [{'op': 'put', 'id': 1}, {'op': 'delete', 'id': 1}, {'op': 'put', 'id': 2}]
    return {'query': {'actions': actions}, 'note': {'hypothesis': 'SQLite AUTOINCREMENT tracks sqlite_sequence, so deleting the max row does not lower the next id; parent tracks only current max and predicts 2.'}}

