def investigate(context, acquire):
    table = {}
    high = 0
    saved = None
    for action in context['actions']:
        op = action['op']
        if op == 'put':
            ident = action['id']
            if ident in table:
                raise ValueError('id already present in current transactional view')
            table[ident] = True
            if ident > high:
                high = ident
        elif op == 'delete':
            table.pop(action['id'], None)
        elif op == 'begin':
            if saved is not None:
                raise ValueError('transactions cannot nest')
            saved = (dict(table), high)
        elif op == 'commit':
            if saved is None:
                raise ValueError('commit requires an open transaction')
            saved = None
        elif op == 'rollback':
            if saved is None:
                raise ValueError('rollback requires an open transaction')
            table, high = saved
            saved = None
    return high + 1

